// The deck's slide text against the brief: its research with numbered sources, the attendees and what they care about, the hardest
// questions and risks, and what the presenter offers and wants (docs/CONTRACT.md, POST /deck-review)
const req = $('A deck was uploaded (laptop)').first().json.body;
const row = $input.first().json || {};
const parse = x => { try { return x ? JSON.parse(x) : null; } catch (e) { return null; } };
const brief = parse(row.brief) || {};
const proposal = parse(row.proposal) || {};
const sources = (brief.sources || []).slice(0, 12);
const research = [brief.company && brief.company.what_they_do ? 'What they do: ' + brief.company.what_they_do : '']
  .concat(((brief.company && brief.company.recent_news) || []).map(n => 'News' + (n.date ? ' (' + n.date + ')' : '') + ': ' + n.text))
  .concat(sources.map((x, i) => '[' + (i + 1) + '] ' + x.title + ' ' + x.url)).filter(Boolean).join('\n') || 'No research saved for this meeting.';
const goal = req.goal || (proposal.goal && proposal.goal.text) || '';
const offer = (req.presenter && req.presenter.offer) || '';
const slides = ((req.deck && req.deck.slides) || []).map(s => ({ index: s.index, text: String(s.text || '').slice(0, 1200) })).filter(s => s.text);
const parts = {
  meeting: (row.title || 'A meeting') + (row.company ? ' with ' + row.company : ''),
  side: (offer ? 'They offer: ' + offer + '. ' : '') + (goal ? 'They want: ' + goal + '.' : '') || 'Not given.',
  brief: JSON.stringify({ summary: brief.summary || '', attendees: brief.attendees || [], questions: (brief.questions || []).map(q => q.question), risks: brief.risks || [] }),
  research,
  deck: JSON.stringify(slides),
};
const PROMPT = "You check a presenter's deck before a real meeting, against what is known about the people they will pitch to.\nFind where the deck will get pushback in this meeting, and from whom.\n\nThe meeting: {meeting}\nWhat the presenter offers and wants from it: {side}\nThe brief (real attendees and what they care about, the hardest questions, the risks):\n{brief}\nThe research on the company, with numbered sources:\n{research}\nThe deck, slide by slide (index from 0):\n{deck}\n\nitems: 3 to 5, the strongest first, each:\n- slide_index: the slide it is about;\n- claim: the claim on that slide, copied or closely paraphrased from its text (e.g. \"30% lower fuel cost\");\n- pushback: what they know or care about that challenges it, in one or two sentences, from the research or the brief only\n  (e.g. \"Their FY25 report says fuel cost already fell 18%, so they will ask what is left to save\"). If nothing in the research\n  contradicts it but nothing supports it either, say what evidence they will ask for;\n- source: the number of the research source it rests on, or 0 if it comes from the brief or is a claim with nothing behind it;\n- who: who will push, an attendee's name from the brief with their focus in brackets, or a role if no attendee fits;\n- fix: what to change on the slide or what to say, in one sentence.\nsummary: one sentence on how the deck will land with this panel.\nNever state facts that are not in the brief or the research, and never invent facts about the presenter's own product.\nAnswer in JSON.";
const prompt = Object.entries(parts).reduce((t, [k, v]) => t.split('{' + k + '}').join(v), PROMPT);
const indexes = ((req.deck && req.deck.slides) || []).map(s => s.index);
return [{ json: { meeting_id: row.meeting_id || '', found: !!row.meeting_id, slides: slides.length, indexes, sources, prompt } }];

